import static ca.yorku.eecs3311.usedcar.FoundationChecks.check;

public final class ReportChecks {
    public static class Fake implements LLMClient {
        public int reportCalls,riskCalls;public boolean fail,low;public String fixed,prompt,schema;
        public String status(){return "OFFLINE REPORT FIXTURE";}
        public String generate(String p){throw new AssertionError("Report must use existing structured API");}
        public String generateStructured(String p,String s){
            if(p.startsWith("Generate an advisory purchase")){reportCalls++;prompt=p;schema=s;if(fail)throw new IllegalStateException("fictional-private-provider-error");return fixed==null?response(p):fixed;}
            if(p.startsWith("Generate clarification"))return ClarificationChecks.response(s);
            if(p.contains("Required checklist: "))return ChecklistChecks.response(p);
            riskCalls++;String result=RiskChecks.response(p);return low?result.replace("Moderate","Low"):result;
        }
    }
    public static String response(String prompt){
        String prefix="Approved report sections: ";String line=prompt.lines().filter(s->s.startsWith(prefix)).findFirst().orElseThrow();
        var j=JsonParser.parseString(line.substring(prefix.length())).getAsJsonObject();j.addProperty("category","Consider with Caution");
        j.addProperty("explanation","Given the saved priorities, review uncertainty and any buyer conflicts before deciding. Obtain an independent professional inspection.");return j.toString();
    }
    public static Map<String,String> corolla(){var v=ClarificationChecks.corolla();v.put("accident","NO");v.put("maintenance","DOCUMENTED");v.put("consumption","7.2");v.put("budget","15000");v.put("maxMileage","150000");v.put("acceptedTransmissions","AUTOMATIC");v.put("preferredBodyType","SEDAN");v.put("reliabilityPriority","5");v.put("fuelEconomyPriority","3");v.put("accidentTolerance","");v.put("annualKm","15000");v.put("fuelPrice","1.65");v.put("taxRate","0.13");v.put("maintenanceAllowance","1000");v.put("insuranceAllowance","1800");return v;}
    public static UsedCarApplicationFacade saved(LLMClient client){var f=RiskChecks.facade(client);PreparationForm.command(f,corolla()).execute();return f;}
    private static void rejects(Runnable call){try{call.run();}catch(IllegalArgumentException|IllegalStateException expected){return;}throw new AssertionError("Expected safe rejection");}
    private static JsonObject json(ReportEvaluation r){return new Gson().toJsonTree(r.requireReport()).getAsJsonObject();}
    private static void invalid(JsonObject j,ReportEvidence e){rejects(()->new ResponseParser().validateReport(new ResponseParser().parseReport(j.toString()),e));}
    public static void generation(){var llm=new Fake();var f=saved(llm);f.evaluateCurrentVehicle();var r=f.generateCurrentReport();check(r.status().equals("AI_SUCCESS")&&r.report().category().equals("Consider with Caution"),"Actual agent/facade pipeline creates typed report");check(llm.reportCalls==1&&llm.riskCalls==1&&r.evidence().risk()!=null,"Reuse current F08 without hidden requests");}
    public static void categories(){var f=saved(new Fake());var r=f.generateCurrentReport();for(String c:EvaluationReport.CATEGORIES){var j=json(r);j.addProperty("category",c);check(new ResponseParser().parseReport(j.toString()).category().equals(c),"Original categories must parse");}var j=json(r);j.addProperty("category","Buy Now");rejects(()->new ResponseParser().parseReport(j.toString()));}
    public static void sections(){var r=saved(new Fake()).generateCurrentReport();check(!r.report().strengths().isEmpty()&&!r.report().risks().isEmpty()&&!r.report().missingInformation().isEmpty()&&!r.report().costSummary().isBlank()&&!r.report().inspectionPriorities().isEmpty()&&!r.report().nextSteps().isEmpty(),"Every original report section must be populated where evidence exists");check(r.report().constraintConflicts().isEmpty(),"No invented constraints");}
    public static void costs(){var r=saved(new Fake()).generateCurrentReport();var c=r.evidence().deterministic().cost();check(c.annualFuelUse().compareTo(new BigDecimal("1080"))==0&&c.annualFuelCost().compareTo(new BigDecimal("1782"))==0&&c.purchaseTax().compareTo(new BigDecimal("1625"))==0&&c.firstYearEstimate().compareTo(new BigDecimal("18707"))==0,"Exact fictional Corolla costs must come from Java");check(r.report().costSummary().equals(r.evidence().costSummary()),"Report preserves authoritative costs");}
    public static void currentInputs(){var llm=new Fake();var f=saved(llm);var v=corolla();v.put("mileage","130000");f.saveVehicle(PreparationForm.vehicle(f,v));f.savePreferences(UserPreference.limits(new BigDecimal("12000"),120000));var r=f.generateCurrentReport();check(r.evidence().deterministic().vehicle().mileage()==130000&&r.evidence().deterministic().preference().maxBudget().intValue()==12000&&r.report().constraintConflicts().size()==2,"Latest saved vehicle and preferences drive evidence");}
    public static void strategy(){var llm=new Fake();var f=saved(llm);f.generateCurrentReport();check(llm.prompt.contains("Reliability Focused"),"Factory selects from actual buyer priorities");f.selectStrategy("budget");check(f.currentReport().isEmpty(),"Strategy change invalidates cached report");f.generateCurrentReport();check(llm.prompt.contains("Budget Focused"),"Manual strategy must influence actual recommendation prompt");}
    public static void conflicts(){var llm=new Fake();var f=saved(llm);f.savePreferences(UserPreference.limits(new BigDecimal("10000"),100000));var r=f.generateCurrentReport();check(r.report().constraintConflicts().size()==2&&r.report().risks().containsAll(r.report().constraintConflicts()),"Hard constraint conflicts cannot be omitted");var j=json(r);j.addProperty("category","Strong Candidate");invalid(j,r.evidence());j=json(r);j.add("constraintConflicts",new JsonArray());invalid(j,r.evidence());j=json(r);j.addProperty("explanation","All buyer constraints are satisfied.");invalid(j,r.evidence());}
    public static void noKnowledge(){var r=saved(new Fake()).generateCurrentReport();check(r.evidence().deterministic().knowledge().equals(VehicleKnowledge.noData())&&r.report().missingInformation().stream().anyMatch(s->s.contains("No matching local")),"No Corolla CSV match remains explicitly unavailable");}
    public static void insufficient(){var llm=new Fake();var f=saved(llm);var v=corolla();v.put("accident","UNKNOWN");f.saveVehicle(PreparationForm.vehicle(f,v));var r=f.generateCurrentReport();check(r.status().equals("INSUFFICIENT_INFORMATION")&&r.report().category().equals("Insufficient Information")&&llm.reportCalls==0&&llm.riskCalls==0,"Essential unknown must gate AI and retain uncertainty");}
    public static void unavailable(){var llm=new Fake();llm.fail=true;var f=saved(llm);var r=f.generateCurrentReport();String text=ReportText.format(r);check(r.status().equals("AI_UNAVAILABLE")&&r.report()==null&&text.contains("18707.00")&&text.contains("Advisory category: UNAVAILABLE")&&!text.contains("fictional-private"),"Provider failure retains costs and no fabricated category/error body");}
    public static void missingKey(){var r=saved(new GeminiAdapter("",null)).generateCurrentReport();check(r.report()==null&&r.status().equals("AI_UNAVAILABLE")&&r.evidence().deterministic().cost()!=null,"Actual unconfigured adapter retains deterministic evidence");}
    public static void malformed(){var llm=new Fake();var f=saved(llm);for(String raw:List.of("","null","[]","{} trailing","not json","{\"category\":\"High Risk\",\"category\":\"Strong Candidate\"}")){llm.fixed=raw;check(f.generateCurrentReport().status().equals("AI_UNAVAILABLE"),"Malformed/duplicate JSON must fail safely");}}
    public static void structure(){var r=saved(new Fake()).generateCurrentReport();for(String name:json(r).keySet()){var j=json(r);j.remove(name);rejects(()->new ResponseParser().parseReport(j.toString()));}var j=json(r);j.addProperty("risks","not an array");rejects(()->new ResponseParser().parseReport(j.toString()));var extra=json(r);extra.addProperty("extra","arbitrary");rejects(()->new ResponseParser().parseReport(extra.toString()));}
    public static void tampering(){var f=saved(new Fake());var r=f.generateCurrentReport();var before=f.currentVehicle();var j=json(r);j.addProperty("costSummary","First year CAD 1");invalid(j,r.evidence());j=json(r);j.getAsJsonArray("strengths").add("Guaranteed safe vehicle");invalid(j,r.evidence());j=json(r);j.add("missingInformation",new JsonArray());invalid(j,r.evidence());check(f.currentVehicle().equals(before),"Parser cannot mutate saved vehicle");}
    public static void ageClaims(){var r=saved(new Fake()).generateCurrentReport();for(String bad:List.of("This is a six year old car.","This vehicle is 6 years old.","This vehicle is six years old.","The engine has damage.","Carfax confirms a clean history.","The vehicle is certified safe.")){var j=json(r);j.addProperty("explanation",bad);invalid(j,r.evidence());}int year=java.time.Year.now().getValue();check(ReportText.format(r).contains("Model-year difference: "+(year-2018)+" years (reference year "+year),"Year arithmetic must be Java-controlled and explicit");}
    public static void missingRisk(){var llm=new Fake();var r=saved(llm).generateCurrentReport();check(r.evidence().risk()==null&&r.report().missingInformation().stream().anyMatch(s->s.contains("risk assessment unavailable"))&&llm.riskCalls==0&&llm.reportCalls==1,"Missing risk must be marked unavailable without implicit F08 calls");var j=json(r);j.addProperty("category","Strong Candidate");invalid(j,r.evidence());}
    public static void strongCandidate(){var llm=new Fake();llm.low=true;var f=saved(llm);f.evaluateCurrentVehicle();var r=f.generateCurrentReport();check(r.evidence().strongAllowed(),"Known low prior risk and satisfied checks permit advisory Strong Candidate");var j=json(r);j.addProperty("category","Strong Candidate");check(new ResponseParser().validateReport(new ResponseParser().parseReport(j.toString()),r.evidence()).category().equals("Strong Candidate"),"Not a permanently disabled original category");}
    public static void riskProse(){var llm=new Fake(){public String generateStructured(String p,String s){var out=super.generateStructured(p,s);if(!p.startsWith("Generate an advisory"))return out.replace("Advisory interpretation of the supplied evidence; review unresolved risks before proceeding.","This car is six years old.");return out;}};var f=saved(llm);f.evaluateCurrentVehicle();var r=f.generateCurrentReport();check(r.evidence().risk()!=null&&!llm.prompt.contains("six years old")&&!ReportText.format(r).contains("six years old"),"Unverified prior F08 prose must not leak into F12 factual output/prompt");}
    public static void clarification(){var llm=new Fake();var f=saved(llm);f.generateCurrentReport();var cycle=f.revisitClarification(ClarificationField.CONSUMPTION);f.submitClarification(cycle.cycleId(),ClarificationField.CONSUMPTION,"8");var pending=f.generateCurrentReport();check(pending.status().equals("INSUFFICIENT_INFORMATION")&&f.currentVehicle().orElseThrow().fuelConsumption().compareTo(new BigDecimal("7.2"))==0,"Pending conflict preserves old value and blocks confident report");f.resolveClarification(cycle.cycleId(),ClarificationField.CONSUMPTION,true);check(f.currentReport().isEmpty(),"Accepted clarification invalidates report");var r=f.generateCurrentReport();check(r.evidence().deterministic().cost().annualFuelUse().compareTo(new BigDecimal("1200"))==0&&r.evidence().clarificationHistory().stream().anyMatch(s->s.contains("ACCEPTED")),"Accepted consumption flows through cost recomputation and report history");}
    public static void vehicleInvalidation(){var llm=new Fake();var f=saved(llm);f.evaluateCurrentVehicle();f.generateCurrentReport();var v=corolla();v.put("price","13000");f.saveVehicle(PreparationForm.vehicle(f,v));check(f.currentReport().isEmpty()&&f.lastRiskEvaluation().isEmpty(),"Vehicle edit invalidates prior risk/report");var r=f.generateCurrentReport();check(r.evidence().risk()==null&&r.evidence().deterministic().vehicle().askingPrice().intValue()==13000,"Changed vehicle cannot reuse stale risk");}
    public static void preferenceInvalidation(){var f=saved(new Fake());f.evaluateCurrentVehicle();f.generateCurrentReport();f.savePreferences(UserPreference.limits(new BigDecimal("1"),null));check(f.currentReport().isEmpty()&&f.lastRiskEvaluation().isEmpty(),"Changed profile invalidates risk/report");check(!f.generateCurrentReport().report().constraintConflicts().isEmpty(),"New budget must apply");}
    public static void switchVehicle(){var f=saved(new Fake());f.generateCurrentReport();var v=f.currentVehicle().orElseThrow();f.saveVehicle(new Vehicle("other",v.year(),"Other",v.model(),v.trim(),v.mileage(),v.askingPrice(),v.transmission(),v.fuelType(),v.accidentHistory(),v.maintenanceHistory(),v.fuelConsumption(),""));check(f.currentReport().isEmpty(),"Vehicle switch isolates report");check(!f.generateCurrentReport().evidence().deterministic().vehicle().id().equals(v.id()),"New report belongs to selected vehicle");}
    public static void cached(){var llm=new Fake();var f=saved(llm);var r=f.generateCurrentReport();for(int i=0;i<5;i++)check(f.currentReport().orElseThrow()==r,"Saved immutable report retained");check(llm.reportCalls==1,"Showing cached report never requests Gemini");}
    public static void staleGeneration(){var ref=new AtomicReference<UsedCarApplicationFacade>();var llm=new Fake(){public String generateStructured(String p,String s){if(p.startsWith("Generate an advisory"))ref.get().savePreferences(UserPreference.limits(new BigDecimal("1"),null));return super.generateStructured(p,s);}};var f=saved(llm);ref.set(f);rejects(f::generateCurrentReport);check(f.currentReport().isEmpty(),"Late result cannot save after evidence change");}
    public static void duplicateGeneration(){var ref=new AtomicReference<UsedCarApplicationFacade>();var llm=new Fake(){public String generateStructured(String p,String s){if(p.startsWith("Generate an advisory"))rejects(()->ref.get().generateCurrentReport());return super.generateStructured(p,s);}};var f=saved(llm);ref.set(f);f.generateCurrentReport();check(llm.reportCalls==1,"Duplicate in-flight generation must not charge twice");}
    public static void checklistNotInspection(){var f=saved(new Fake());var checklist=f.generateCurrentChecklist();for(var i:checklist.checklist().items())f.completeChecklistItem(checklist.generationId(),i.id(),true);var r=f.generateCurrentReport();check(r.report().nextSteps().contains(ReportEvidence.INSPECTION)&&r.report().missingInformation().stream().anyMatch(s->s.contains("not a professional inspection")),"Checked boxes cannot certify condition or remove inspection recommendation");}
    public static void noVehicle(){var f=RiskChecks.facade(new Fake());rejects(f::generateCurrentReport);check(f.currentReport().isEmpty(),"Missing vehicle leaves no report");}
    public static void missingCosts(){var f=RiskChecks.facade(new Fake());f.saveVehicle(PreparationForm.vehicle(f,corolla()));var r=f.generateCurrentReport();check(r.evidence().deterministic().cost()==null&&r.report().costSummary().contains("unavailable"),"No assumptions means no invented costs");}
    public static void toolFailure(){var tools=new ToolManager();tools.registerTool("constraints",input->{throw new IllegalStateException("fixture");});tools.registerTool("vehicleKnowledge",new VehicleKnowledgeTool(new VehicleKnowledgeRepository()));var llm=new Fake();var f=new UsedCarApplicationFacade(new UsedCarAgent(tools,llm,new DataQualityChecker()),new EvaluationSession());f.saveVehicle(PreparationForm.vehicle(f,corolla()));var r=f.generateCurrentReport();check(r.status().equals("INSUFFICIENT_INFORMATION")&&llm.reportCalls==0&&r.report().missingInformation().stream().anyMatch(s->s.contains("Constraint tool failed")),"Mandatory tool failure must gate synthesis and identify unavailable evidence");}
    public static void costToolFailure(){var tools=new ToolManager();tools.registerTool("constraints",new ConstraintCheckerTool());tools.registerTool("vehicleKnowledge",input->{throw new IllegalStateException("fixture");});tools.registerTool("cost",input->{throw new IllegalStateException("fixture");});var session=new EvaluationSession();var f=new UsedCarApplicationFacade(new UsedCarAgent(tools,new Fake(),new DataQualityChecker()),session);f.saveVehicle(PreparationForm.vehicle(f,corolla()));session.setCostAssumptions(new CostAssumptions(new BigDecimal("15000"),new BigDecimal("1.65"),null,null,null));var r=f.generateCurrentReport();check(r.report()!=null&&r.evidence().deterministic().cost()==null&&r.report().missingInformation().stream().anyMatch(s->s.contains("cost tool failed")),"Optional cost/knowledge failures retain available evidence without invented amounts");}
    private static Path directory(){try{var root=Path.of("build","verification");Files.createDirectories(root);return Files.createTempDirectory(root,"f12-test-");}catch(IOException e){throw new AssertionError(e);}}
    public static void export(){var f=saved(new Fake());var v=corolla();v.put("trim","LE 测试");f.saveVehicle(PreparationForm.vehicle(f,v));var r=f.generateCurrentReport();var path=directory().resolve("Report Review.txt");f.exportReport(r.generationId(),path);try{check(Files.readString(path).equals(ReportText.format(r))&&Files.readString(path).contains("测试"),"Export is exact UTF-8 text with case/spaces preserved");}catch(IOException e){throw new AssertionError(e);}}
    public static void exportSafety(){var f=saved(new Fake());var r=f.generateCurrentReport();var path=directory().resolve("existing.txt");try{Files.writeString(path,"KEEP ORIGINAL");}catch(IOException e){throw new AssertionError(e);}rejects(()->f.exportReport(r.generationId(),path));try{check(Files.readString(path).equals("KEEP ORIGINAL"),"Export never overwrites existing files");}catch(IOException e){throw new AssertionError(e);}rejects(()->f.exportReport(r.generationId(),path.toAbsolutePath().getRoot()));rejects(()->f.exportReport(r.generationId(),path.resolveSibling("wrong.pdf")));rejects(()->f.exportReport(r.generationId(),path.resolveSibling("missing-folder").resolve("x.txt")));}
    public static void staleExport(){var f=saved(new Fake());var r=f.generateCurrentReport();var path=directory().resolve("stale.txt");f.savePreferences(UserPreference.limits(null,null));rejects(()->f.exportReport(r.generationId(),path));check(!Files.exists(path),"Stale report cannot be exported as current");}
    public static void cli(){var llm=new Fake();var f=saved(llm);var path=directory().resolve("CLI Report.txt");var out=new ByteArrayOutputStream();new UsedCarCLI(f,new Scanner("report\nreport-show\nreport-save "+path+"\nreport-save "+path+"\nquit\n"),new PrintStream(out)).run();String text=out.toString();check(text.contains("F12 PERSONALIZED")&&text.contains("AI_SUCCESS")&&text.contains("A. DETERMINISTIC")&&text.contains("B. GEMINI")&&text.contains("already exists")&&Files.exists(path)&&llm.reportCalls==1,"CLI uses production generation/show/export and safe errors");}
    public static void cliInsufficient(){var llm=new Fake();var f=saved(llm);var v=corolla();v.put("maintenance","UNKNOWN");f.saveVehicle(PreparationForm.vehicle(f,v));var out=new ByteArrayOutputStream();new UsedCarCLI(f,new Scanner("report\nreport-show\nquit\n"),new PrintStream(out)).run();check(out.toString().contains("INSUFFICIENT_INFORMATION")&&llm.reportCalls==0,"CLI preserves missing history and avoids request");}
    public static void promptPrivacy(){var llm=new Fake();var f=saved(llm);var v=corolla();v.put("notes","fictional-private-advertisement");f.saveVehicle(PreparationForm.vehicle(f,v));f.generateCurrentReport();check(!llm.prompt.contains("fictional-private-advertisement")&&llm.prompt.contains("untrusted")&&llm.prompt.contains("referenceYear"),"Prompt sends structured context with explicit reference year, not raw notes");}
    public static void immutable(){var r=saved(new Fake()).generateCurrentReport();try{r.report().risks().clear();throw new AssertionError("Immutable report required");}catch(UnsupportedOperationException expected){}try{r.evidence().clarificationHistory().add("bad");throw new AssertionError("Immutable history required");}catch(UnsupportedOperationException expected){}}
    public static void originalContract(){var f=saved(new Fake());var v=f.currentVehicle().orElseThrow();check(f.generateReport(v).category().equals("Consider with Caution"),"Original facade generateReport(Vehicle) delegates to real workflow");var other=ClarificationField.MILEAGE.apply(v,"1");rejects(()->f.generateReport(other));}
    public static void runAll(){staleRiskSnapshot();combinedUncertainty();insufficientPriorRisk();generation();categories();sections();costs();currentInputs();strategy();conflicts();noKnowledge();insufficient();unavailable();missingKey();malformed();structure();tampering();ageClaims();missingRisk();strongCandidate();riskProse();clarification();vehicleInvalidation();preferenceInvalidation();switchVehicle();cached();staleGeneration();duplicateGeneration();checklistNotInspection();noVehicle();missingCosts();toolFailure();costToolFailure();export();exportSafety();staleExport();cli();cliInsufficient();promptPrivacy();immutable();originalContract();}

    private static UsedCarAgent realAgent(LLMClient llm){var tools=new ToolManager();tools.registerTool("cost",new CostCalculatorTool());tools.registerTool("constraints",new ConstraintCheckerTool());tools.registerTool("vehicleKnowledge",new VehicleKnowledgeTool(new VehicleKnowledgeRepository()));return new UsedCarAgent(tools,llm,new DataQualityChecker());}
    public static void staleRiskSnapshot(){var llm=new Fake();var f=saved(llm);var risk=f.evaluateCurrentVehicle();var vehicle=ClarificationField.MILEAGE.apply(f.currentVehicle().orElseThrow(),"140000");
        var r=realAgent(llm).generateRecommendation(vehicle,f.preferences(),null,f.costAssumptions().orElseThrow(),risk,null,Set.of());
        check(r.evidence().risk()==null&&r.evidence().riskStatus().contains("unavailable"),"Agent rejects even explicitly supplied stale F08 snapshots");}
    public static void combinedUncertainty(){var llm=new Fake();var f=RiskChecks.facade(llm);var values=corolla();for(String key:List.of("trim","transmission","fuelType","accident","maintenance","consumption"))values.put(key,"");values.put("make","UNKNOWN");values.put("model","UNKNOWN");
        var vehicle=PreparationForm.vehicle(f,values);var profile=new UserPreference(new BigDecimal("15000"),150000,Set.of("AUTOMATIC"),"",5,3,"NO_ACCIDENTS");
        var responses=new LinkedHashMap<ClarificationField,ClarificationResponse>();for(var field:List.of(ClarificationField.PRICE,ClarificationField.MILEAGE,ClarificationField.YEAR))responses.put(field,new ClarificationResponse("CONFLICT","proposed",field.read(vehicle),"proposed"));
        var state=new ClarificationState("fixture",vehicle,new ClarificationBatch("USER_REQUESTED","fixture",List.of()),responses,List.of());
        var r=realAgent(llm).generateRecommendation(vehicle,profile,null,new CostAssumptions(new BigDecimal("15000"),new BigDecimal("1.65"),null,null,null),null,state,Set.of(ClarificationField.values()));
        check(r.status().equals("INSUFFICIENT_INFORMATION")&&r.report().missingInformation().size()>40&&llm.reportCalls==0,"Combined real missing fields, listing ambiguity, conflicts and cost limits must fit without dropping evidence or crashing");
        check(new ResponseParser().parseReport(new Gson().toJson(r.report())).equals(r.report()),"Full bounded report remains parseable");}
    public static void insufficientPriorRisk(){var llm=new Fake(){public String generateStructured(String p,String s){String value=super.generateStructured(p,s);return p.startsWith("Generate an advisory")?value:value.replace("Moderate","Insufficient Information");}};
        var f=saved(llm);f.evaluateCurrentVehicle();var r=f.generateCurrentReport();check(r.status().equals("INSUFFICIENT_INFORMATION")&&llm.reportCalls==0,"Current F08 insufficiency cannot silently become favorable recommendation");}
}
